-- DormNamo backend: every file in supabase/migrations, in order. Generated by `npm run db:bundle`;
-- edit the migrations, not this file. Safe to run again: nothing here drops your data.

-- =========== 20261125000100_tables.sql ===========
-- 01 Tables
-- Safe on a project that already has them: the first version was created by hand in the SQL
-- editor, so every statement here only adds what is missing and never drops data.

create table if not exists public.profiles (
  id uuid primary key references auth.users on delete cascade,
  name text not null,
  roles text[] default '{student}',
  bio text, school text, phone text, show_phone boolean default false,
  created_at timestamptz default now()
);
alter table public.profiles add column if not exists avatar_url text;
alter table public.profiles add column if not exists updated_at timestamptz default now();

-- owner listings (same terse fields as HOUSES in shared/js/data/data.js)
create table if not exists public.listings (
  ref uuid primary key default gen_random_uuid(),   -- the DN- reference number
  owner_id uuid references public.profiles on delete cascade,
  n text not null, brgy text, street text, addr text, s text, t text,
  p int, c text, ds text, am text[] default '{}', facts jsonb default '{}',
  plan text default 'basic', pay text default 'full', f boolean default false,
  cover text, photos text[] default '{}',
  created_at timestamptz default now(), updated_at timestamptz default now()
);
alter table public.listings add column if not exists a text;                          -- area shown on cards (= barangay)
alter table public.listings add column if not exists lat double precision;
alter table public.listings add column if not exists lng double precision;
alter table public.listings add column if not exists requested_plan text default 'basic'; -- what the owner picked; `plan` is what was paid
alter table public.listings add column if not exists hidden boolean default false;
alter table public.listings alter column owner_id set default auth.uid();

-- each student's preferences, swipes and learning-model weights (the S object)
create table if not exists public.user_state (
  user_id uuid primary key references public.profiles on delete cascade,
  state jsonb not null, updated_at timestamptz default now()
);

-- chats: one-to-one ("dm", may carry a deal) and one tenant group per listing
create table if not exists public.threads (
  id uuid primary key default gen_random_uuid(),
  kind text check (kind in ('dm', 'group')),
  listing_ref uuid references public.listings on delete cascade,
  members uuid[] not null, status text default 'inquiry', offer jsonb,
  updated_at timestamptz default now()
);
alter table public.threads add column if not exists roles jsonb not null default '{}';    -- {uid: "owner" | "student" | "tenant"}
alter table public.threads add column if not exists read_at jsonb not null default '{}';  -- {uid: last read time}
alter table public.threads add column if not exists created_at timestamptz default now();

create table if not exists public.messages (
  id bigint generated always as identity primary key,
  thread_id uuid references public.threads on delete cascade,
  sender uuid references public.profiles, text text, data jsonb,
  created_at timestamptz default now()
);
alter table public.messages add column if not exists kind text not null default 'text';
alter table public.messages alter column sender set default auth.uid();
-- keep the conversation when one side deletes their account
alter table public.messages drop constraint if exists messages_sender_fkey;
alter table public.messages
  add constraint messages_sender_fkey foreign key (sender) references public.profiles (id) on delete set null;

-- comments with tenant star ratings; owner listings use listing_ref, Google Maps places listing_id
create table if not exists public.comments (
  id bigint generated always as identity primary key,
  listing_ref uuid, listing_id int,
  user_id uuid references public.profiles on delete cascade,
  text text, stars int check (stars between 1 and 5),
  created_at timestamptz default now()
);
alter table public.comments alter column user_id set default auth.uid();

-- hearts = saved / popular (never the star rating)
create table if not exists public.hearts (
  user_id uuid references public.profiles on delete cascade,
  listing_key text,                    -- listing ref, or the Google Maps place id
  primary key (user_id, listing_key)
);
alter table public.hearts alter column user_id set default auth.uid();
alter table public.hearts add column if not exists created_at timestamptz default now();

-- paid plans: written only by the server (service role / admin), never by the browser
create table if not exists public.subscriptions (
  user_id uuid primary key references public.profiles on delete cascade,
  plan text not null check (plan in ('pro-m', 'pro-y')),
  status text not null default 'active' check (status in ('active', 'past_due', 'canceled')),
  current_period_end timestamptz not null,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

-- Featured boosts: written only by the server; 3 Featured places per barangay at a time
create table if not exists public.boosts (
  id bigint generated always as identity primary key,
  listing_ref uuid not null references public.listings on delete cascade,
  kind text not null check (kind in ('b7', 'b30', 'bsem')),
  starts_at timestamptz not null default now(),
  ends_at timestamptz not null,
  created_at timestamptz default now(),
  check (ends_at > starts_at)
);

-- indexes for the queries the site makes
create index if not exists listings_owner_idx on public.listings (owner_id);
create index if not exists listings_brgy_idx on public.listings (brgy);
create index if not exists threads_members_idx on public.threads using gin (members);
create index if not exists threads_listing_idx on public.threads (listing_ref);
create index if not exists messages_thread_idx on public.messages (thread_id, created_at);
create index if not exists comments_ref_idx on public.comments (listing_ref);
create index if not exists comments_id_idx on public.comments (listing_id);
create index if not exists comments_user_idx on public.comments (user_id);
create index if not exists messages_sender_idx on public.messages (sender);
create index if not exists hearts_key_idx on public.hearts (listing_key);
create index if not exists boosts_listing_idx on public.boosts (listing_ref, ends_at);

-- data rules, added once
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'profiles_roles_ok') then
    alter table public.profiles add constraint profiles_roles_ok
      check (roles <@ array['student', 'owner']::text[] and cardinality(roles) between 1 and 2);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'profiles_name_len') then
    alter table public.profiles add constraint profiles_name_len check (char_length(name) between 1 and 80);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'listings_rent_ok') then
    alter table public.listings add constraint listings_rent_ok check (p is null or p between 0 and 100000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'listings_plan_ok') then
    alter table public.listings add constraint listings_plan_ok
      check (plan in ('basic', 'b7', 'b30', 'bsem', 'pro-m', 'pro-y')
         and coalesce(requested_plan, 'basic') in ('basic', 'b7', 'b30', 'bsem', 'pro-m', 'pro-y'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'threads_status_ok') then
    alter table public.threads add constraint threads_status_ok
      check (status is null or status in ('inquiry', 'negotiating', 'agreed', 'declined'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'messages_kind_ok') then
    alter table public.messages add constraint messages_kind_ok
      check (kind in ('text', 'photo', 'interest', 'offer', 'system'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'messages_text_len') then
    alter table public.messages add constraint messages_text_len check (char_length(coalesce(text, '')) <= 4000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'comments_text_len') then
    alter table public.comments add constraint comments_text_len check (char_length(coalesce(text, '')) <= 2000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'comments_target') then
    alter table public.comments add constraint comments_target check (listing_ref is not null or listing_id is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'user_state_size') then
    alter table public.user_state add constraint user_state_size check (octet_length(state::text) <= 300000);
  end if;
end $$;

-- =========== 20261125000200_accounts.sql ===========
-- 02 Accounts: profile on sign-up, private fields, public view, updated_at

-- keep updated_at honest on every table that has it
create or replace function public.touch_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['profiles', 'listings', 'user_state', 'threads', 'subscriptions'] loop
    execute format('drop trigger if exists touch_updated_at on public.%I', t);
    execute format(
      'create trigger touch_updated_at before update on public.%I for each row execute function public.touch_updated_at()', t);
  end loop;
end $$;

-- a profile row for every new login (name and roles come from the sign-up form's metadata)
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  meta jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  r text[];
begin
  select coalesce(array_agg(distinct x), '{}'::text[]) into r
    from jsonb_array_elements_text(
      case when jsonb_typeof(meta -> 'roles') = 'array' then meta -> 'roles' else '[]'::jsonb end) as x
   where x in ('student', 'owner');
  if cardinality(r) = 0 then r := array['student']; end if;

  insert into public.profiles (id, name, roles)
  values (new.id,
          left(coalesce(nullif(trim(meta ->> 'name'), ''), split_part(new.email, '@', 1), 'Student'), 80),
          r)
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users for each row execute function public.handle_new_user();

-- profiles: you read and edit only your own row (phone, school…)
alter table public.profiles enable row level security;
drop policy if exists "read profiles" on public.profiles;
drop policy if exists "edit own profile" on public.profiles;
drop policy if exists "profiles: read own" on public.profiles;
drop policy if exists "profiles: update own" on public.profiles;
create policy "profiles: read own" on public.profiles
  for select to authenticated using ((select auth.uid()) = id);
create policy "profiles: update own" on public.profiles
  for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
-- no insert policy: rows are made by handle_new_user. No delete: the delete-account function does it.

-- what anyone may see about a person (Accounts.person / people / owners):
-- never the email, and the phone only when they chose to show it.
-- Reading other people's rows needs more rights than the visitor has, so that one step lives in a
-- function in the `private` schema, which the API doesn't expose. The view itself runs with the
-- visitor's own rights (security_invoker), as Supabase's security advisor asks.
create schema if not exists private;
revoke all on schema private from public;

create or replace function private.public_profile_rows()
returns table (id uuid, name text, roles text[], bio text, school text, phone text,
               avatar_url text, created_at timestamptz, places int)
language sql stable security definer set search_path = '' as $$
  select p.id, p.name, p.roles, p.bio, p.school,
         case when p.show_phone then p.phone end,
         p.avatar_url, p.created_at,
         (select count(*)::int from public.listings l
           where l.owner_id = p.id and not coalesce(l.hidden, false))
    from public.profiles p
$$;

-- the first version of this view ran with its owner's rights; replace it
drop view if exists public.public_profiles;
create view public.public_profiles with (security_invoker = true) as
  select * from private.public_profile_rows();
comment on view public.public_profiles is
  'Public profile fields only: no email, phone only when show_phone. Rows come from private.public_profile_rows().';

-- =========== 20261125000300_listings_and_plans.sql ===========
-- 03 Listings and plans: who may change what, the 2 / 5 place limit, Featured spots
-- The browser can never set `plan`, `f` (featured) or `owner_id` on an update: those columns
-- are not granted (see 08_grants). Plans and boosts are written only by the server after payment.

alter table public.listings enable row level security;
drop policy if exists "read listings" on public.listings;
drop policy if exists "own listings" on public.listings;
drop policy if exists "listings: read visible" on public.listings;
drop policy if exists "listings: add own" on public.listings;
drop policy if exists "listings: edit own" on public.listings;
drop policy if exists "listings: delete own" on public.listings;
create policy "listings: read visible" on public.listings
  for select using (not coalesce(hidden, false) or owner_id = (select auth.uid()));
create policy "listings: add own" on public.listings
  for insert to authenticated with check (owner_id = (select auth.uid()));
create policy "listings: edit own" on public.listings
  for update to authenticated using (owner_id = (select auth.uid())) with check (owner_id = (select auth.uid()));
create policy "listings: delete own" on public.listings
  for delete to authenticated using (owner_id = (select auth.uid()));

alter table public.subscriptions enable row level security;
drop policy if exists "subscriptions: read own" on public.subscriptions;
create policy "subscriptions: read own" on public.subscriptions
  for select to authenticated using (user_id = (select auth.uid()));

alter table public.boosts enable row level security;
drop policy if exists "boosts: read" on public.boosts;
create policy "boosts: read" on public.boosts for select using (true);

-- how many places someone may list: Basic 2, Owner Pro 5 (Listings.LIMIT in listings.js)
drop function if exists public.listing_limit(uuid);
create or replace function private.listing_limit(uid uuid)
returns int language sql stable security definer set search_path = '' as $$
  select case when exists (
           select 1 from public.subscriptions s
            where s.user_id = uid and s.status = 'active' and s.current_period_end > now())
         then 5 else 2 end
$$;

-- refuse a new place past the limit; listing a place makes you a landowner
create or replace function public.check_listing_quota()
returns trigger language plpgsql security definer set search_path = '' as $$
declare
  used int;
  cap int;
begin
  -- one owner's inserts wait for each other, so two tabs can't both slip past the limit
  perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text, 0));
  select count(*) into used from public.listings where owner_id = new.owner_id;
  cap := private.listing_limit(new.owner_id);
  if used >= cap then
    raise exception 'listing_limit'
      using detail = format('%s of %s places used', used, cap),
            hint = case when cap < 5 then 'Owner Pro lists up to 5 places.' else 'This is the Owner Pro maximum.' end;
  end if;

  update public.profiles
     set roles = array(select distinct r from unnest(roles || array['owner']) as r)
   where id = new.owner_id and not ('owner' = any (roles));
  return new;
end $$;

drop trigger if exists listing_quota on public.listings;
create trigger listing_quota
  before insert on public.listings for each row execute function public.check_listing_quota();

-- at most 3 Featured places per barangay at the same time (owners.js SPOTS)
create or replace function public.check_boost_spots()
returns trigger language plpgsql set search_path = '' as $$
declare
  b text;
  taken int;
begin
  select brgy into b from public.listings where ref = new.listing_ref;
  select count(distinct x.listing_ref) into taken
    from public.boosts x join public.listings l on l.ref = x.listing_ref
   where l.brgy is not distinct from b
     and x.listing_ref <> new.listing_ref
     and x.starts_at < new.ends_at and x.ends_at > new.starts_at;
  if taken >= 3 then
    raise exception 'no_featured_spots' using detail = coalesce(b, 'This area') || ' already has 3 Featured places';
  end if;
  return new;
end $$;

drop trigger if exists boost_spots on public.boosts;
create trigger boost_spots
  before insert on public.boosts for each row execute function public.check_boost_spots();

-- which places are Featured right now (cards and Discover show the badge from this)
create or replace view public.featured_listings with (security_invoker = true) as
  select b.listing_ref, l.brgy, max(b.ends_at) as until
    from public.boosts b
    join public.listings l on l.ref = b.listing_ref
   where now() between b.starts_at and b.ends_at
   group by b.listing_ref, l.brgy;

-- Featured spots left in a barangay (owners.js bill() "spots left")
create or replace function public.featured_spots_left(p_brgy text)
returns int language sql stable set search_path = '' as $$
  select greatest(0, 3 - count(*)::int)
    from public.featured_listings where brgy is not distinct from p_brgy
$$;

-- =========== 20261125000400_messaging.sql ===========
-- 04 Messages and deals (Inbox in shared/js/account/inbox.js)
-- Members read their chats. Plain text and photos are inserted directly; everything that changes
-- a deal or who is in a chat goes through the functions below, which check the rules:
--   inquiry -> negotiating (any offer; a newer one replaces the open one)
--           -> agreed (the OTHER side answers yes; the student joins the place's tenant group)
--           -> declined (only the landowner closes)

alter table public.threads enable row level security;
drop policy if exists "member threads" on public.threads;
drop policy if exists "threads: members read" on public.threads;
create policy "threads: members read" on public.threads
  for select to authenticated using ((select auth.uid()) = any (members));

alter table public.messages enable row level security;
drop policy if exists "member messages" on public.messages;
drop policy if exists "send as yourself" on public.messages;
drop policy if exists "messages: members read" on public.messages;
drop policy if exists "messages: send text or photo" on public.messages;
create policy "messages: members read" on public.messages
  for select to authenticated using (
    exists (select 1 from public.threads t where t.id = thread_id and (select auth.uid()) = any (t.members)));
create policy "messages: send text or photo" on public.messages
  for insert to authenticated with check (
    sender = (select auth.uid())
    and kind in ('text', 'photo')
    and exists (select 1 from public.threads t where t.id = thread_id and (select auth.uid()) = any (t.members)));

-- a new message moves its chat to the top
create or replace function public.bump_thread()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  update public.threads set updated_at = now() where id = new.thread_id;
  return new;
end $$;
drop trigger if exists bump_thread on public.messages;
create trigger bump_thread after insert on public.messages for each row execute function public.bump_thread();

-- "I'm interested · Message": open (or reuse) the chat with the place's landowner
create or replace function private.start_interest(p_listing uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  own uuid;
  tid uuid;
begin
  if me is null then raise exception 'login_required'; end if;
  select owner_id into own from public.listings where ref = p_listing and not coalesce(hidden, false);
  if own is null then raise exception 'no_landowner'; end if;
  if own = me then raise exception 'own_listing'; end if;

  select id into tid from public.threads
   where kind = 'dm' and listing_ref = p_listing and members @> array[me, own]
   limit 1;
  if tid is null then
    insert into public.threads (kind, listing_ref, members, roles, status)
    values ('dm', p_listing, array[me, own],
            jsonb_build_object(me::text, 'student', own::text, 'owner'), 'inquiry')
    returning id into tid;
    insert into public.messages (thread_id, sender, kind, text, data)
    values (tid, me, 'interest', '', jsonb_build_object('listing', p_listing));
  end if;
  return tid;
end $$;

-- a plain one-to-one chat with someone (Landowners page "Message")
create or replace function private.start_dm(p_user uuid)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  tid uuid;
  role_of jsonb;
begin
  if me is null then raise exception 'login_required'; end if;
  if p_user is null or p_user = me then raise exception 'bad_person'; end if;
  if not exists (select 1 from public.profiles where id = p_user) then raise exception 'bad_person'; end if;

  select id into tid from public.threads
   where kind = 'dm' and listing_ref is null and members @> array[me, p_user] and cardinality(members) = 2
   limit 1;
  if tid is null then
    select jsonb_object_agg(id::text, case when 'owner' = any (roles) then 'owner' else 'student' end)
      into role_of from public.profiles where id in (me, p_user);
    insert into public.threads (kind, listing_ref, members, roles, status)
    values ('dm', null, array[me, p_user], role_of, null)
    returning id into tid;
  end if;
  return tid;
end $$;

-- make an offer (rent, move-in date, note); replaces the open one
create or replace function private.send_offer(p_thread uuid, p_rent int, p_move date default null, p_note text default null)
returns bigint language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  t public.threads;
  mid bigint;
  o jsonb;
begin
  select * into t from public.threads where id = p_thread for update;
  if t.id is null or not (me = any (t.members)) then raise exception 'not_a_member'; end if;
  if t.kind <> 'dm' or t.listing_ref is null then raise exception 'no_deal_here'; end if;
  if t.status in ('agreed', 'declined') then raise exception 'deal_closed'; end if;
  if p_rent is null or p_rent < 0 or p_rent > 100000 then raise exception 'bad_rent'; end if;

  update public.messages set data = jsonb_set(data, '{state}', '"replaced"')
   where thread_id = p_thread and kind = 'offer' and data ->> 'state' = 'open';

  o := jsonb_build_object('rent', p_rent, 'move', p_move, 'note', left(p_note, 500), 'state', 'open');
  insert into public.messages (thread_id, sender, kind, text, data)
  values (p_thread, me, 'offer', '', o)
  returning id into mid;

  update public.threads
     set status = 'negotiating',
         offer = (o - 'state') || jsonb_build_object('by', me, 'message', mid)
   where id = p_thread;
  return mid;
end $$;

-- answer an offer: only the other side; yes = agreed and the student joins the tenant group
create or replace function private.answer_offer(p_message bigint, p_yes boolean)
returns text language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  m public.messages;
  t public.threads;
  own uuid;
  student uuid;
  g uuid;
begin
  select * into m from public.messages where id = p_message for update;
  if m.id is null or m.kind <> 'offer' then raise exception 'no_offer'; end if;
  select * into t from public.threads where id = m.thread_id for update;
  if not (me = any (t.members)) then raise exception 'not_a_member'; end if;
  if m.sender = me then raise exception 'answer_own_offer'; end if;
  if coalesce(m.data ->> 'state', '') <> 'open' then raise exception 'offer_not_open'; end if;

  if not p_yes then
    update public.messages set data = jsonb_set(data, '{state}', '"declined"') where id = m.id;
    return t.status;
  end if;

  update public.messages set data = jsonb_set(data, '{state}', '"accepted"') where id = m.id;
  update public.threads set status = 'agreed' where id = t.id;

  select owner_id into own from public.listings where ref = t.listing_ref;
  select x into student from unnest(t.members) as x where x <> own limit 1;

  select id into g from public.threads where kind = 'group' and listing_ref = t.listing_ref limit 1;
  if g is null then
    insert into public.threads (kind, listing_ref, members, roles, status)
    values ('group', t.listing_ref, array[own], jsonb_build_object(own::text, 'owner'), null)
    returning id into g;
  end if;
  if student is not null then
    update public.threads
       set members = array_append(members, student),
           roles = roles || jsonb_build_object(student::text, 'tenant')
     where id = g and not (student = any (members));
    insert into public.messages (thread_id, sender, kind, text) values (g, null, 'system', 'A new tenant joined.');
  end if;
  return 'agreed';
end $$;

-- the landowner ends a deal
create or replace function private.close_thread(p_thread uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  t public.threads;
begin
  select * into t from public.threads where id = p_thread for update;
  if t.id is null or not (me = any (t.members)) then raise exception 'not_a_member'; end if;
  if coalesce(t.roles ->> me::text, '') <> 'owner' then raise exception 'landowner_only'; end if;
  update public.messages set data = jsonb_set(data, '{state}', '"declined"')
   where thread_id = p_thread and kind = 'offer' and data ->> 'state' = 'open';
  update public.threads set status = 'declined' where id = p_thread;
end $$;

-- a tenant leaves the group; the landowner can't leave their own place's group
create or replace function private.leave_group(p_thread uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  t public.threads;
begin
  select * into t from public.threads where id = p_thread for update;
  if t.id is null or t.kind <> 'group' or not (me = any (t.members)) then raise exception 'not_a_member'; end if;
  if t.roles ->> me::text = 'owner' then raise exception 'owner_stays'; end if;
  update public.threads set members = array_remove(members, me), roles = roles - me::text where id = p_thread;
end $$;

-- the landowner removes a tenant from the group
create or replace function private.remove_tenant(p_thread uuid, p_user uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  me uuid := auth.uid();
  t public.threads;
begin
  select * into t from public.threads where id = p_thread for update;
  if t.id is null or t.kind <> 'group' or coalesce(t.roles ->> me::text, '') <> 'owner' then
    raise exception 'landowner_only';
  end if;
  if p_user = me then raise exception 'owner_stays'; end if;
  update public.threads set members = array_remove(members, p_user), roles = roles - p_user::text where id = p_thread;
end $$;

-- unread counts (Inbox.unread): remember when each member last read a chat
create or replace function private.mark_read(p_thread uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare me uuid := auth.uid();
begin
  update public.threads
     set read_at = read_at || jsonb_build_object(me::text, now())
   where id = p_thread and me = any (members);
end $$;

-- The functions above live in `private` (not reachable through the API) and run with extra rights.
-- The site calls these thin public versions, which run with the caller's own rights
-- (security invoker), as Supabase's security advisor recommends. Same names and arguments.
create or replace function public.start_interest(p_listing uuid)
returns uuid language sql security invoker set search_path = '' as $$
  select private.start_interest(p_listing)
$$;
create or replace function public.start_dm(p_user uuid)
returns uuid language sql security invoker set search_path = '' as $$
  select private.start_dm(p_user)
$$;
create or replace function public.send_offer(p_thread uuid, p_rent int, p_move date default null, p_note text default null)
returns bigint language sql security invoker set search_path = '' as $$
  select private.send_offer(p_thread, p_rent, p_move, p_note)
$$;
create or replace function public.answer_offer(p_message bigint, p_yes boolean)
returns text language sql security invoker set search_path = '' as $$
  select private.answer_offer(p_message, p_yes)
$$;
create or replace function public.close_thread(p_thread uuid)
returns void language sql security invoker set search_path = '' as $$
  select private.close_thread(p_thread)
$$;
create or replace function public.leave_group(p_thread uuid)
returns void language sql security invoker set search_path = '' as $$
  select private.leave_group(p_thread)
$$;
create or replace function public.remove_tenant(p_thread uuid, p_user uuid)
returns void language sql security invoker set search_path = '' as $$
  select private.remove_tenant(p_thread, p_user)
$$;
create or replace function public.mark_read(p_thread uuid)
returns void language sql security invoker set search_path = '' as $$
  select private.mark_read(p_thread)
$$;

-- live updates: the other person's browser hears new messages and deal changes
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'messages') then
      alter publication supabase_realtime add table public.messages;
    end if;
    if not exists (select 1 from pg_publication_tables
                    where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'threads') then
      alter publication supabase_realtime add table public.threads;
    end if;
  end if;
end $$;

-- =========== 20261125000500_comments_hearts_state.sql ===========
-- 05 Comments, hearts and each student's saved state

-- your preferences, swipes and model weights are private
alter table public.user_state enable row level security;
drop policy if exists "own state" on public.user_state;
drop policy if exists "user_state: own" on public.user_state;
create policy "user_state: own" on public.user_state
  for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- comments: everyone reads; you add and delete only your own
alter table public.comments enable row level security;
drop policy if exists "read comments" on public.comments;
drop policy if exists "own comments" on public.comments;
drop policy if exists "comments: read" on public.comments;
drop policy if exists "comments: add own" on public.comments;
drop policy if exists "comments: delete own" on public.comments;
create policy "comments: read" on public.comments for select using (true);
create policy "comments: add own" on public.comments
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy "comments: delete own" on public.comments
  for delete to authenticated using (user_id = (select auth.uid()));

-- stars: one rating per person per place (the latest wins), and owners can't rate their own place
create or replace function public.comment_rules()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if new.stars is not null then
    if new.listing_ref is not null and exists (
         select 1 from public.listings l where l.ref = new.listing_ref and l.owner_id = new.user_id) then
      new.stars := null;
    else
      update public.comments
         set stars = null
       where user_id = new.user_id and stars is not null
         and listing_ref is not distinct from new.listing_ref
         and listing_id is not distinct from new.listing_id;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists comment_rules on public.comments;
create trigger comment_rules before insert on public.comments for each row execute function public.comment_rules();

create or replace view public.comment_stats with (security_invoker = true) as
  select coalesce(listing_ref::text, listing_id::text) as listing_key,
         count(*)::int as comments,
         count(stars)::int as ratings,
         round(avg(stars)::numeric, 2) as stars
    from public.comments
   group by 1;

-- hearts: everyone sees the counts; you heart and un-heart only for yourself
alter table public.hearts enable row level security;
drop policy if exists "read hearts" on public.hearts;
drop policy if exists "own hearts" on public.hearts;
drop policy if exists "hearts: read" on public.hearts;
drop policy if exists "hearts: add own" on public.hearts;
drop policy if exists "hearts: remove own" on public.hearts;
create policy "hearts: read" on public.hearts for select using (true);
create policy "hearts: add own" on public.hearts
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy "hearts: remove own" on public.hearts
  for delete to authenticated using (user_id = (select auth.uid()));

create or replace view public.heart_counts with (security_invoker = true) as
  select listing_key, count(*)::int as hearts from public.hearts group by listing_key;

-- =========== 20261125000600_storage.sql ===========
-- 06 File storage
-- listing-photos: public to view (cards and the dialog show them), each owner writes only into
--   listing-photos/<their user id>/...
-- chat-photos: private; only the chat's members upload and view, at chat-photos/<thread id>/...
-- Both accept JPEG, PNG and WebP up to 5 MB (the site shrinks photos before upload anyway).

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('listing-photos', 'listing-photos', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('chat-photos', 'chat-photos', false, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
on conflict (id) do update
  set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- listing photos (names match the first version, so re-running replaces them)
drop policy if exists "upload own photos" on storage.objects;
drop policy if exists "change own photos" on storage.objects;
drop policy if exists "delete own photos" on storage.objects;
create policy "upload own photos" on storage.objects for insert to authenticated
  with check (bucket_id = 'listing-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "change own photos" on storage.objects for update to authenticated
  using (bucket_id = 'listing-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);
create policy "delete own photos" on storage.objects for delete to authenticated
  using (bucket_id = 'listing-photos' and (storage.foldername(name))[1] = (select auth.uid())::text);

-- chat photos
drop policy if exists "chat photos: members upload" on storage.objects;
drop policy if exists "chat photos: members view" on storage.objects;
create policy "chat photos: members upload" on storage.objects for insert to authenticated
  with check (
    bucket_id = 'chat-photos'
    and exists (select 1 from public.threads t
                 where t.id::text = (storage.foldername(name))[1] and (select auth.uid()) = any (t.members)));
create policy "chat photos: members view" on storage.objects for select to authenticated
  using (
    bucket_id = 'chat-photos'
    and exists (select 1 from public.threads t
                 where t.id::text = (storage.foldername(name))[1] and (select auth.uid()) = any (t.members)));

-- =========== 20261125000700_grants.sql ===========
-- 07 Grants: exactly what the browser's key may touch. Row Level Security then narrows it to
-- the right rows. Columns not listed (plan, f, owner_id on update, subscriptions, boosts) can only
-- be changed by the server: the SQL editor, an Edge Function or the service role.

grant usage on schema public to anon, authenticated;

-- start from nothing, then allow
revoke all on all tables in schema public from anon, authenticated;

-- public reading (logged out too)
grant select on public.listings, public.comments, public.hearts, public.boosts to anon, authenticated;
grant select on public.public_profiles, public.featured_listings, public.comment_stats, public.heart_counts
  to anon, authenticated;

-- your own profile
grant select on public.profiles to authenticated;
grant update (name, roles, bio, school, phone, show_phone, avatar_url) on public.profiles to authenticated;

-- your own listings (never plan / f; owner_id only when adding, and RLS makes it yours)
grant insert (owner_id, n, a, brgy, street, addr, s, t, p, c, ds, am, facts, requested_plan, pay,
              cover, photos, lat, lng, hidden) on public.listings to authenticated;
grant update (n, a, brgy, street, addr, s, t, p, c, ds, am, facts, requested_plan, pay,
              cover, photos, lat, lng, hidden) on public.listings to authenticated;
grant delete on public.listings to authenticated;

-- your saved state
grant select, insert, update, delete on public.user_state to authenticated;

-- chats: read; send text and photos; everything else through the functions
grant select on public.threads, public.messages to authenticated;
grant insert (thread_id, sender, kind, text, data) on public.messages to authenticated;

-- comments and hearts
grant insert (listing_ref, listing_id, user_id, text, stars) on public.comments to authenticated;
grant delete on public.comments to authenticated;
grant insert (user_id, listing_key) on public.hearts to authenticated;
grant delete on public.hearts to authenticated;

-- your plan (read only)
grant select on public.subscriptions to authenticated;

-- functions: the chat and plan helpers for logged-in people; nothing for anonymous visitors
revoke execute on all functions in schema public from public, anon;
grant execute on function
  public.start_interest(uuid),
  public.start_dm(uuid),
  public.send_offer(uuid, int, date, text),
  public.answer_offer(bigint, boolean),
  public.close_thread(uuid),
  public.leave_group(uuid),
  public.remove_tenant(uuid, uuid),
  public.mark_read(uuid),
  public.featured_spots_left(text)
to authenticated;
grant execute on function public.featured_spots_left(text) to anon;

-- public_profiles reads through this one function; the private schema is not exposed by the API
grant usage on schema private to anon, authenticated;
revoke execute on all functions in schema private from public;
grant execute on function private.public_profile_rows() to anon, authenticated;
-- the deal functions' bodies, reached only through their public versions
grant execute on function
  private.start_interest(uuid),
  private.start_dm(uuid),
  private.send_offer(uuid, int, date, text),
  private.answer_offer(bigint, boolean),
  private.close_thread(uuid),
  private.leave_group(uuid),
  private.remove_tenant(uuid, uuid),
  private.mark_read(uuid)
to authenticated;

-- =========== 20261125000800_descriptions.sql ===========
-- 08 Descriptions: what every table and column is for. Supabase shows these in the Table Editor
-- and the Schema Visualizer, so the project documents itself. Safe to re-run.

-- schemas
comment on schema public is 'DormNamo app data, reachable through the API (protected by RLS and grants).';
comment on schema private is 'Helper functions the API does not expose.';

-- people
comment on table public.profiles is 'One row per login (made by handle_new_user). Others see people through public_profiles.';
comment on column public.profiles.id is 'Same id as auth.users.';
comment on column public.profiles.name is 'Display name, 1 to 80 characters.';
comment on column public.profiles.roles is 'student and/or owner (landowner). Listing a place adds owner.';
comment on column public.profiles.phone is 'Format 09XX XXX XXXX. Shown to others only when show_phone is true.';
comment on column public.profiles.show_phone is 'Let others see the phone number.';
comment on column public.profiles.avatar_url is 'Profile photo (optional).';

comment on table public.user_state is 'Each student''s private saved state: preferences, likes, passes, activity log, learning-model weights (the S object).';
comment on column public.user_state.state is 'JSON of S from shared/js/app/state.js, up to 300 KB.';

-- listings
comment on table public.listings is 'Places landowners add. Google Maps places stay in shared/js/data/data.js.';
comment on column public.listings.ref is 'Permanent reference number, shown as DN- plus its first 8 characters.';
comment on column public.listings.owner_id is 'The landowner. Set to the logged-in person when added; cannot be changed.';
comment on column public.listings.n is 'Name of the place.';
comment on column public.listings.a is 'Area shown on cards (the barangay).';
comment on column public.listings.brgy is 'Barangay in Iligan City.';
comment on column public.listings.street is 'Street or purok (optional).';
comment on column public.listings.addr is 'Full address made from street + barangay.';
comment on column public.listings.s is 'Nearest school (e.g. MSU-IIT).';
comment on column public.listings.t is 'Room type: Boarding house, Dormitory, Apartment…';
comment on column public.listings.p is 'Monthly rent in pesos. Empty = rate on request (never guessed).';
comment on column public.listings.c is 'Contact number.';
comment on column public.listings.ds is 'Description written by the landowner.';
comment on column public.listings.am is 'Amenities the landowner states (Wi-Fi, CR inside…).';
comment on column public.listings.facts is 'Facts the landowner states (water, curfew, gender…). A missing key means unknown.';
comment on column public.listings.requested_plan is 'Plan the landowner picked; becomes plan once paid.';
comment on column public.listings.plan is 'Plan in effect (basic, b7, b30, bsem, pro-m, pro-y). Server only.';
comment on column public.listings.pay is 'full or parts (pay in parts).';
comment on column public.listings.f is 'Featured right now. Server only.';
comment on column public.listings.cover is 'Cover photo URL (listing-photos bucket).';
comment on column public.listings.photos is 'Room photo URLs (listing-photos bucket).';
comment on column public.listings.lat is 'Map pin latitude.';
comment on column public.listings.lng is 'Map pin longitude.';
comment on column public.listings.hidden is 'Hidden from everyone but the landowner (e.g. paused or removed by the team).';

comment on table public.subscriptions is 'Owner Pro plans. Written only by the team (admin.sql) or a payment function. Active = up to 5 places.';
comment on table public.boosts is 'Featured boosts. Written only by the team or a payment function. At most 3 at a time per barangay.';
comment on column public.boosts.kind is 'b7 = 7 days, b30 = 30 days, bsem = semester.';

-- chats
comment on table public.threads is 'Chats. dm = one-to-one (may carry a deal); group = a place''s tenant group. Changed only through the deal functions.';
comment on column public.threads.kind is 'dm or group.';
comment on column public.threads.listing_ref is 'The place this chat is about (empty for a plain chat).';
comment on column public.threads.members is 'Who is in the chat. Only they can read it.';
comment on column public.threads.roles is 'Role of each member: owner, student or tenant.';
comment on column public.threads.status is 'Deal status: inquiry, negotiating, agreed, declined (empty for plain chats and groups).';
comment on column public.threads.offer is 'The open offer: rent, move-in date, note, who made it.';
comment on column public.threads.read_at is 'When each member last read the chat (for unread counts).';

comment on table public.messages is 'Messages in a chat. People send text and photos; offers, interest cards and system lines come from the deal functions.';
comment on column public.messages.kind is 'text, photo, interest, offer or system.';
comment on column public.messages.sender is 'Who sent it. Empty for system lines or a deleted account.';
comment on column public.messages.data is 'Extra details: photo URLs, or the offer (rent, move, note, state).';

-- feedback
comment on table public.comments is 'Comments on a place, with an optional 1-5 star rating. One rating per person per place (latest wins); owners can''t rate their own place.';
comment on column public.comments.listing_ref is 'For places landowners added.';
comment on column public.comments.listing_id is 'For Google Maps places (their id in data.js).';
comment on table public.hearts is 'Saved rooms (a heart = a Discover like). Counts are public; never part of the star rating.';
comment on column public.hearts.listing_key is 'Listing ref, or the Google Maps place id.';

-- views
comment on view public.featured_listings is 'Places Featured right now, with their barangay.';
comment on view public.comment_stats is 'Per place: number of comments, ratings and the average stars.';
comment on view public.heart_counts is 'Per place: number of hearts.';
